# Let me try to find a pattern that works for all cases
inputs = ['iyhb', 'ac', 'cehfdw', 'ay', 'vbbvf']
outputs = ['iubwhb', 'ac', 'cuhfkvw', 'aubw', 'vbbvf']

# Try to identify common subpatterns
print("Looking for repeated patterns:")

# Check for character substitutions
substitutions = {}
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                if (inp[j], out[j]) not in substitutions:
                    substitutions[(inp[j], out[j])] = 1
                else:
                    substitutions[(inp[j], out[j])] += 1

print("Character substitutions found:")
for (old, new), count in substitutions.items():
    print(f"  '{old}' -> '{new}' (seen {count} times)")

# Check for longer patterns
print("\nChecking for longer patterns...")
long_patterns = {}
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        # Look for substring matches that could be replaced
        for length in range(2, min(len(inp), len(out)) + 1):
            for start in range(len(inp) - length + 1):
                substr = inp[start:start+length]
                # Check if this substring appears in output at corresponding location
                if start + length <= len(out):
                    expected = out[start:start+length]
                    if substr != expected:
                        if (substr, expected) not in long_patterns:
                            long_patterns[(substr, expected)] = 1
                        else:
                            long_patterns[(substr, expected)] += 1

print("Multi-character patterns found:")
for (old, new), count in long_patterns.items():
    print(f"  '{old}' -> '{new}' (seen {count} times)")

